ROWS = [
dict(id="T087", d="PERC", t="Existence and values of the critical exponents of three-dimensional percolation",
 s="For Bernoulli bond percolation on Z^3 the critical exponents exist: θ(p) = (p − p_c)^{β+o(1)} as p ↓ p_c, the mean cluster size is (p_c − p)^{−γ+o(1)} as p ↑ p_c, the correlation length is |p − p_c|^{−ν+o(1)}, and at p_c the one-arm probability P(0 ↔ ∂B_n) is n^{−1/ρ+o(1)} and the two-point function decays like |x|^{−(1+η)+o(1)}; and they satisfy the scaling and hyperscaling relations, for example γ = ν(2 − η) and 3ν = γ + 2β.",
 c="Existence of the exponents is part of the problem. Their values are known only numerically (β ≈ 0.418, ν ≈ 0.876, η ≈ −0.046, from 1/ν = 1.1410(15) and β/ν = 0.47705(15) for bond and site percolation on the cubic lattice: Wang, Zhou, Zhang, Garoni and Deng, arXiv:1302.0421, Phys. Rev. E 87 (2013)); no exact values are conjectured. Continuity at p_c (T001) would be a first step.",
 src="H. Kesten, Scaling relations for 2D-percolation, Comm. Math. Phys. 109 (1987); G. Grimmett, Percolation, 2nd ed. (Springer, 1999)",
 loc="Grimmett 1999, Chapter 9 (Near the Critical Point: Scaling Theory) and Chapter 10 (Near the Critical Point: Rigorous Results)",
 why="Critical exponents are the central quantitative prediction of the theory of phase transitions. In three dimensions there is no exact solution and no lace expansion, so the problem tests whether any method reaches genuinely three-dimensional criticality.",
 st="In d = 2 the exponents are known for site percolation on the triangular lattice (Smirnov 2001; Lawler–Schramm–Werner 2002; Smirnov–Werner 2001, through Kesten's scaling relations). Mean-field values (β = γ = 1, ν = 1/2) hold for d ≥ 11 (Hara–Slade 1990; Fitzner–van der Hofstad 2017) and for spread-out models with d > 6. For 3 ≤ d ≤ 6 no exponent is known to exist, and θ(p_c) = 0 is open for 3 ≤ d ≤ 10 (T001). Some inequalities hold in every dimension, for example γ ≥ 1 (Aizenman–Newman, J. Stat. Phys. 36 (1984)) and β ≤ 1 (Chayes–Chayes, Phys. Rev. Lett. 56 (1986); Aizenman–Barsky, Comm. Math. Phys. 108 (1987), who also get δ ≥ 2). A short proof of the mean-field lower bound on θ is in Duminil-Copin–Tassion, arXiv:1502.03050."),
dict(id="T088", d="PERC", t="The chemical-distance exponent of planar critical percolation",
 s="For critical site percolation on the triangular lattice, let S_n be the length of the shortest open left-right crossing of an n × n box, on the event that one exists, so that S_n = n^{d_min+o(1)}. Determine d_min (numerically d_min ≈ 1.1306), and prove that the same exponent governs critical bond percolation on Z^2.",
 c="Existence of d_min on the triangular lattice, through convergence of the intrinsic metric, is proved in arXiv:2604.14122 (2026, Corollary 1.2, for the conditional mean and the quantiles of S_n). No closed form is conjectured; unlike the other planar percolation exponents, d_min is not expected to come out of SLE(6) by a known computation.",
 src="O. Schramm, Conformally invariant scaling limits: an overview and a collection of problems, Proc. ICM 2006, vol. I, arXiv:math/0602151; M. Aizenman and A. Burchard, Hölder regularity and dimension bounds for random curves, Duke Math. J. 99 (1999)",
 loc="Schramm 2006, Problem 3.3 (exponent of the expected length of the shortest crossing)",
 why="The graph metric of the critical cluster is the intrinsic geometry of percolation; it governs random walk on the incipient cluster and first-passage times at criticality, and it is the most prominent planar percolation exponent that SLE has not delivered.",
 st="S_n ≥ n^{1+ε} with high probability (Aizenman–Burchard 1999). The lowest crossing has length n^{4/3+o(1)} (Morrow–Zhang, arXiv:math/0508459, Ann. Appl. Probab. 2005), and E S_n ≤ n^{−δ} E L_n for the lowest crossing L_n, so the exponent is below 4/3 (Damron–Hanson–Sosoe, arXiv:1708.03643, Comm. Pure Appl. Math. 2021). Dankovic, Markering, Miller and Yuan (arXiv:2604.14122) prove convergence of the intrinsic metric and of random walk on triangular-lattice critical clusters, and existence of d_min. The value and universality across lattices are open. Numerical estimate d_min = 1.13077(2) (Zhou–Yang–Deng–Ziff, arXiv:1112.3428, Phys. Rev. E 2012), which rules out the conjectured 217/192.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T089", d="RMT", t="The Bohigas–Giannoni–Schmit conjecture",
 s="For a classically chaotic quantum system, for example the Dirichlet Laplacian on a planar billiard Ω whose billiard flow is ergodic and hyperbolic (the Bunimovich stadium, the Sinai billiard), restricted to one symmetry class and with time-reversal symmetry, let x_j = |Ω|λ_j/4π be the eigenvalues unfolded by Weyl's law. As Λ → ∞, the x_j with λ_j in [Λ, 2Λ] have the local statistics of the Gaussian Orthogonal Ensemble; in particular the nearest-neighbour spacing distribution converges to the GOE (Gaudin) law.",
 c="Arithmetic examples (hyperbolic surfaces from quaternion algebras) have Poisson-like statistics, so a theorem needs a genericity hypothesis, and there is no agreed form of one. Bohigas, Giannoni and Schmit (doi:10.1103/PhysRevLett.52.1) state the conjecture from numerics on the Sinai billiard.",
 src="O. Bohigas, M.-J. Giannoni and C. Schmit, Characterization of chaotic quantum spectra and universality of level fluctuation laws, Phys. Rev. Lett. 52 (1984), 1–4",
 why="BGS is the founding conjecture of quantum chaos and the reason random-matrix statistics are expected in physical spectra; it is the deterministic counterpart of Wigner–Dyson universality.",
 st="GOE statistics are not proved for any chaotic billiard or manifold. Support comes from periodic-orbit expansions of the spectral form factor (Berry 1985; Sieber–Richter 2001; Müller–Heusler–Braun–Haake–Altland 2004) and from numerics. Rigorous results concern eigenfunctions rather than eigenvalues: quantum ergodicity (Shnirelman 1974; Zelditch 1987; Colin de Verdière 1985) and arithmetic quantum unique ergodicity (Lindenstrauss 2006). Arithmetic exceptions: Poisson-like spacings for arithmetic surfaces (Bogomolny–Georgeot–Giannoni–Schmit, Phys. Rev. Lett. 69 (1992), 1477; Bolte–Steil–Steiner, Phys. Rev. Lett. 69 (1992), 2188) and the number variance on arithmetic hyperbolic surfaces (Luo–Sarnak, Comm. Math. Phys. 161 (1994)).",
 n="Statement revised after the w673 audit (14 Oct). Fame borderline in that audit; kept for now."),
dict(id="T090", d="IPS", t="Kardar–Parisi–Zhang growth in 2+1 dimensions",
 s="Random surface growth in 2+1 dimensions in the isotropic KPZ class (the KPZ equation ∂_t h = Δh + λ|∇h|² + ξ in two space dimensions with spatially smoothed noise and fixed λ ≠ 0, or ballistic deposition and the Eden model) has nontrivial universal exponents: the height variance grows like t^{2β} with β ≈ 0.24, the roughness exponent is α ≈ 0.39, and the rescaled height has a non-Gaussian limit.",
 c="The exponents are known only numerically. Isotropy matters: for anisotropic growth (AKPZ) fluctuations are predicted to be logarithmic (Wolf 1991).",
 src="M. Kardar, G. Parisi and Y.-C. Zhang, Dynamic scaling of growing interfaces, Phys. Rev. Lett. 56 (1986); T. Halpin-Healy and Y.-C. Zhang, Kinetic roughening phenomena, stochastic growth, directed polymers and all that, Phys. Rep. 254 (1995)",
 why="Two space dimensions is the physical case of surface growth and the critical dimension of the KPZ nonlinearity; no integrable model is known in the isotropic class, so any progress needs a new method. See T005 for 1+1 dimensions.",
 st="When the coupling is sent to zero like 1/√log of the mollification scale, the limit is the Gaussian Edwards–Wilkinson equation (Chatterjee–Dunlap 2020; Caravenna–Sun–Zygouras, arXiv:1812.03911; Gu 2020), and at the critical coupling the critical 2D stochastic heat flow appears (Caravenna–Sun–Zygouras 2023; see also arXiv:2412.10311 and arXiv:2609.15832). Anisotropic models: logarithmic fluctuations for integrable AKPZ growth (Borodin–Ferrari 2014) and logarithmic superdiffusivity of the stationary AKPZ equation (Cannizzaro–Erhard–Toninelli, arXiv:2009.12934). In the isotropic strong-coupling regime nothing rigorous is known about the exponents, or even about the existence of a non-Gaussian universality class.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T091", d="BM", t="Uniqueness and regularity for the three-dimensional stochastic Navier–Stokes equations",
 s="For the incompressible Navier–Stokes equations on the three-dimensional torus driven by additive Gaussian noise, white in time and smooth in space, prove (a) that Leray–Hopf martingale solutions are unique in law, or (b) that for smooth initial data a global strong solution exists almost surely.",
 c="With smooth additive noise the problem contains the difficulty of deterministic global regularity; the hope behind it, regularization by noise, is that noise of the right structure (for example transport noise) rules out singularities.",
 src="F. Flandoli, An introduction to 3D stochastic fluid dynamics, in SPDE in Hydrodynamic: Recent Progress and Prospects, Lecture Notes in Math. 1942 (Springer, 2008), 51–150; F. Flandoli and D. Gatarek, Martingale and stationary solutions for stochastic Navier–Stokes equations, Probab. Theory Related Fields 102 (1995)",
 why="This is the stochastic form of the Navier–Stokes Millennium problem, where Markov selections, the strong Feller property, ergodicity and convex integration in law meet the question of turbulence.",
 st="Martingale solutions exist (Flandoli–Gatarek 1995). For nondegenerate noise, Da Prato and Debussche (J. Math. Pures Appl. 82 (2003)) build from Galerkin limits a transition semigroup that is strong Feller with a unique invariant measure; Markov selections exist, and every Markov solution is strong Feller for regular enough noise (Flandoli–Romito, arXiv:math/0602612, Probab. Theory Related Fields 140 (2008)). Neither gives uniqueness. Non-uniqueness in law holds for solutions that fail the energy inequality, by convex integration (Hofmanová–Zhu–Zhu, arXiv:1912.11841), and for Leray solutions on R^3 when a suitable deterministic force is added (Brué–Jin–Li–Zhang, arXiv:2309.09753); neither is the unforced Leray–Hopf case on the torus. Global solutions exist with positive probability for small data (Lin–Wang, arXiv:2407.00722). Transport noise delays blow-up with high probability in vorticity form (Flandoli–Luo, arXiv:1910.05742, Probab. Theory Related Fields 180 (2021)). Both (a) and (b) are open.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T092", d="DYN", t="Simple Lebesgue spectrum for a transformation of a probability space (Banach's problem, finite-measure form)",
 s="Is there an invertible measure-preserving transformation T of a probability space (X, μ) whose Koopman operator f ↦ f∘T, restricted to the orthocomplement of the constants in L²(μ), has simple Lebesgue spectrum, that is, is unitarily equivalent to multiplication by z on L²(S¹, Lebesgue measure)?",
 c="Banach's question as recorded by Ulam is for the real line with Lebesgue measure, an infinite measure; for that version el Abdalaoui claims positive answers with conservative maps (arXiv:1508.06439; arXiv:2210.15480). The finite-measure version, which el Abdalaoui attributes to Rokhlin, is the open one (arXiv:2210.15480v2, introduction).",
 src="S. M. Ulam, A Collection of Mathematical Problems (Interscience, 1960), reprinted as Problems in Modern Mathematics (Wiley, 1964), p. 76, where Banach's problem from the Scottish Book is restated; A. Katok and J.-P. Thouvenot, Spectral properties and combinatorial constructions in ergodic theory, in Handbook of Dynamical Systems, vol. 1B (Elsevier, 2006); E. H. el Abdalaoui, L¹-flat polynomials and simple Lebesgue spectrum for conservative maps exist: a simple proof, arXiv:2210.15480",
 loc="el Abdalaoui, arXiv:2210.15480v2, Introduction, pp. 2–3 (distinguishes the two versions)",
 why="Every known transformation with Lebesgue spectrum (Bernoulli and K-automorphisms, Gaussian systems with absolutely continuous spectral measure, horocycle flows) has it with infinite multiplicity; the problem asks whether the spectral type of a chaotic system can be as small as possible, and it is the oldest open question of spectral ergodic theory.",
 st="For probability-preserving transformations, Lebesgue spectrum of finite multiplicity is not known to occur. A Lebesgue component of multiplicity two occurs (Mathew–Nadkarni, Bull. London Math. Soc. 16 (1984)), Lebesgue components of every even multiplicity occur (Ageev, Sb. Math. 64 (1989)), and many other spectral multiplicity sets are realized (survey: Danilenko, arXiv:1104.1961, Ergodic Theory Dynam. Systems 33 (2013)); a Lebesgue component is not pure simple Lebesgue spectrum. Open.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T093", d="RG", t="The colourability threshold of sparse random graphs",
 s="For each fixed q ≥ 3 there is a constant c_q such that G(n, c/n) is q-colourable with probability tending to one when c < c_q and to zero when c > c_q; and c_q equals the value given by the one-step replica-symmetry-breaking cavity method (for example c_3 ≈ 4.687).",
 c="A sharp threshold sequence c_q(n) exists (Achlioptas–Friedgut 1999); its convergence is part of the problem. For random d-regular graphs a sharp colourability threshold is identified only for q above a constant (Coja-Oghlan–Efthymiou–Hetterich, arXiv:1308.4287, J. Combin. Theory Ser. B 116 (2016)); for q = 3, 3-colourability of the random 5-regular graph is proved only under a numerically supported hypothesis (Díaz–Kaporis–Kemkes–Kirousis–Pérez–Wormald, J. Graph Theory 61 (2009)).",
 src="R. Mulet, A. Pagnani, M. Weigt and R. Zecchina, Coloring random graphs, Phys. Rev. Lett. 89 (2002), 268701; F. Krzakała, A. Montanari, F. Ricci-Tersenghi, G. Semerjian and L. Zdeborová, Gibbs states and the set of solutions of random constraint satisfaction problems, Proc. Natl. Acad. Sci. USA 104 (2007)",
 why="Colouring is the canonical sparse random constraint satisfaction problem; with k-SAT (T017) it is the test of whether cavity-method thresholds are exact at small parameter values.",
 st="c_q lies between 2q log q − log q − 2 log 2 + o_q(1) and 2q log q − log q − 1 + o_q(1) (Coja-Oghlan–Vilenchik, arXiv:1304.1063; Coja-Oghlan, arXiv:1305.0177; both 2013), after Achlioptas–Naor (2005). The condensation threshold, found for large q by Bapst–Coja-Oghlan–Hetterich–Rassmann–Vilenchik (arXiv:1404.5513, Comm. Math. Phys. 341 (2016)), is determined for every q ≥ 3 (Coja-Oghlan–Krzakala–Perkins–Zdeborová, arXiv:1611.00814). For q = 3 only bounds are known: G(n, c/n) is 3-colourable for c < 4.03 (Achlioptas–Moore, J. Comput. System Sci. 67 (2003)) and not 3-colourable for c > 4.9364, that is above 2.4682 edges per vertex (Dubois–Mandler, arXiv:math/0209087); the cavity-method prediction is c_3 ≈ 4.69 (Mulet–Pagnani–Weigt–Zecchina, Phys. Rev. Lett. 89 (2002)); existence of the limit is open for every fixed q.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T094", d="SM", t="The number of pure states of the three-dimensional Edwards–Anderson spin glass",
 s="For the Edwards–Anderson Ising spin glass on Z^3 with iid symmetric Gaussian couplings at low temperature, determine the structure of the periodic-boundary-condition metastate: whether it is trivial and supported on a single pair of flip-related pure states (the scaling-droplet and trivial–nontrivial pictures), nontrivial with each sampled Gibbs state a single flip-related pair (chaotic pairs), or nontrivial with each sampled Gibbs state a mixture of infinitely many pure-state pairs with a nontrivial overlap distribution (replica symmetry breaking).",
 c="The pictures are those of Fisher–Huse, of Parisi and of Newman–Stein. Newman and Stein showed that the naive form of replica symmetry breaking cannot hold and proposed metastates as the framework, so the question is stated for metastates; the number of pure states in the support of the metastate and the decomposition of a single sampled Gibbs state are different questions.",
 src="C. M. Newman and D. L. Stein, Spin Glasses and Complexity (Princeton Univ. Press, 2013); D. S. Fisher and D. A. Huse, Equilibrium behavior of the spin-glass ordered phase, Phys. Rev. B 38 (1988)",
 loc="Newman–Read–Stein, Metastates and replica symmetry breaking, arXiv:2204.10345, Section 3, p. 13",
 why="The number of pure states is the defining question about short-range spin glasses and the point where the solved mean-field theory and finite-dimensional physics part ways.",
 st="Metastates exist (Aizenman–Wehr, Comm. Math. Phys. 130 (1990); Newman–Stein, Phys. Rev. E 55 (1997)), and the naive replica-symmetry-breaking scenario with a non-self-averaging overlap distribution in a single state is ruled out (Newman–Stein, Phys. Rev. Lett. 76 (1996), 515). Results on ground states concern two-dimensional half-planes (Arguin–Damron–Newman–Stein, Comm. Math. Phys. 300 (2010)); see T052 for the planar ground-state problem. Even the existence of a low-temperature spin-glass phase is open (T025); arXiv:2407.17506 proves bounds on free-energy fluctuations and records that phase existence and the number of states remain open. Nothing decides the structure of the metastate in any dimension d ≥ 3.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T095", d="PERC", t="Differentiability of the limit shape in first-passage percolation",
 s="For first-passage percolation on Z^2 with iid nonnegative edge weights whose law is continuous and satisfies E min(τ_1, …, τ_4)² < ∞ (the Cox–Durrett condition for the shape theorem; τ_1, …, τ_4 are independent copies), the boundary of the limit shape is differentiable at every point.",
 c="For weights with an atom at the infimum of the support, of mass above the oriented percolation threshold, the shape has flat edges, so some condition on the law is needed; flat edges do not give corners, since the boundary is differentiable at the endpoints of the flat edge (Auffinger–Damron 2013). Uniformly positive curvature is a separate conjecture, part of T050.",
 src="H. Kesten, Aspects of first passage percolation, École d'Été de Probabilités de Saint-Flour XIV, Lecture Notes in Math. 1180 (1986), 125–264; A. Auffinger, M. Damron and J. Hanson, 50 Years of First-Passage Percolation, University Lecture Series 68 (AMS, 2017)",
 loc="Auffinger–Damron–Hanson, arXiv:1511.03262, Sections 2.5–2.8",
 why="Differentiability and curvature of the limit shape are the hypotheses under which most results on geodesics, Busemann functions and fluctuation exponents are proved (Newman 1995; Damron–Hanson 2014); a proof would make them unconditional.",
 st="The shape is compact and convex (Cox–Durrett 1981). Flat edges occur for atoms at the infimum (Durrett–Liggett 1981), with differentiability at the endpoints of the flat segment (Auffinger–Damron 2013; Auffinger–Damron–Hanson, arXiv:1511.03262, Theorem 2.25). No continuous weight distribution is known to give a differentiable boundary; strict convexity is open too (T050). Update, 14 Nov 2026: the OpenAI math release (github.com/openai/math; AI-written, unrefereed) has 'Strict convexity and differentiability of the planar exponential first-passage limit shape' (24 Sep 2026), which claims differentiability everywhere for every Gamma law, exponential included, with Lean material for that claim; general continuous laws remain open.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T096", d="RW", t="Rapid mixing of Glauber dynamics for the Sherrington–Kirkpatrick model up to β = 1",
 s="For the Sherrington–Kirkpatrick model with an arbitrary external field at inverse temperature β < 1, single-site heat-bath Glauber dynamics mixes in time polynomial in n (conjecturally of order n log n) from every starting configuration, with probability tending to one over the disorder.",
 c="β = 1 is the replica-symmetry-breaking threshold of the zero-field model; for β < 1 the Almeida–Thouless condition holds whatever the field, so the whole range is replica symmetric, but it lies outside any Dobrushin-type high-temperature regime.",
 src="A. S. Bandeira, A. Kireeva, A. Maillard and A. Rödder, Randomstrasse101: open problems of 2024, arXiv:2504.20539",
 loc="Bandeira–Kireeva–Maillard–Rödder 2025, Open Problem 15",
 why="SK is the model case of a disordered system with a complex energy landscape; rapid mixing up to β = 1 would show that the whole replica-symmetric phase is easy for the simplest local dynamics, matching the static picture.",
 st="Spectral gap and modified log-Sobolev bounds give rapid mixing for β < 1/4 (Bauerschmidt–Bodineau, arXiv:1712.03676, J. Funct. Anal. 276 (2019); Eldan–Koehler–Zeitouni, arXiv:2007.08200; Anari–Jain–Koehler–Pham–Vuong, arXiv:2106.04105), extended to β < 0.295 (Anari–Koehler–Vuong 2024). Wang (arXiv:2608.22159v2) proves mixing in O_β(n log(n/ε)) steps from every start for β < 1/2, uniformly over external fields, and Boban, Li and Oveis Gharan (arXiv:2609.13138) prove polynomial mixing for β ≤ 1/2 + ε with an absolute ε > 0 (no field is mentioned in the abstract). Other samplers go further but are not fixed-temperature Glauber dynamics: stochastic localization, in Wasserstein distance, for β < 1/2 (El Alaoui–Montanari–Sellke 2022) and through the whole easy regime β < 1 once Celentano (arXiv:2208.09550) proved the local convexity conjecture of El Alaoui et al., and simulated annealing (Glauber dynamics along an increasing inverse-temperature schedule) to accuracy n^{−M} in total variation for every fixed β < 1 (arXiv:2610.09882, Oct 2026, not yet refereed). At low temperature, mixing from a worst-case start is exponentially slow (arXiv:2511.22621). Open between about 1/2 and 1.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T097", d="GF", t="Critical behaviour of level-set percolation of the three-dimensional Gaussian free field",
 s="For the discrete Gaussian free field φ on Z^3, the excursion set {φ ≥ h} has an infinite cluster for h < h_* and none for h > h_*. Determine its behaviour at and near h_*: whether the percolation probability, the correlation length and the one-arm probability at h_* follow power laws, with which exponents, and whether these agree with those of the cable-system field.",
 c="On the metric graph (cable system) the critical level is 0 and several exponents are known exactly; the lattice field has h_* > 0 and is not covered by those results.",
 src="A. Drewitz, A. Prévost and P.-F. Rodriguez, Critical exponents for a percolation model on transient graphs, Invent. Math. 232 (2023), 229–299; H. Duminil-Copin, S. Goswami, P.-F. Rodriguez and F. Severo, Equality of critical parameters for percolation of Gaussian free field level sets, Duke Math. J. 172 (2023)",
 why="GFF level sets are the canonical percolation model with power-law correlations; their criticality tests the Harris–Weinrib criterion for correlated percolation, and isomorphism theorems tie them to random interlacements and loop soups.",
 st="The transition is sharp, h_* = h_** = h̄ (Duminil-Copin–Goswami–Rodriguez–Severo, arXiv:2002.07735), and h_* > 0 on Z^d for every d ≥ 3 (Drewitz–Prévost–Rodriguez, arXiv:1708.03285). On the cable system h_* = 0 (Lupu 2016) and critical exponents are computed in low dimensions (Ding–Wirth, Ann. Probab. 48 (2020); Drewitz–Prévost–Rodriguez, Invent. Math. 232 (2023); Cai–Ding, arXiv:2406.02397, which gives the one-arm probability up to constants for 3 ≤ d ≤ 5); the recent arXiv:2406.02397 and arXiv:2610.03703 are also about the cable system. For the lattice field no critical exponent is known to exist.",
 n="Status updated after the w673 audit (14 Oct). Fame borderline in that audit; kept for now."),
dict(id="T098", d="RMT", t="Stability of many-body localization",
 s="For a one-dimensional spin chain with iid random fields, such as the Ising chain with transverse field H = Σ_i h_i σ_i^z + Σ_i γ_i σ_i^x + Σ_i J_i σ_i^z σ_{i+1}^z with weak transverse terms, at strong disorder every eigenstate is many-body localized in Imbrie's sense: there is a quasi-local unitary that turns H into a function of commuting integrals of motion (l-bits), where quasi-locality is probabilistic, holding away from rare resonant blocks whose probabilities decay with their size, with bounds uniform in the chain length.",
 c="The quantifiers are part of the problem: the statement is for all eigenstates (infinite temperature), not only low energies. Exponential localization at every site, uniformly, is too strong a target, because resonant regions occur with positive density.",
 src="D. M. Basko, I. L. Aleiner and B. L. Altshuler, Metal–insulator transition in a weakly interacting many-electron system with localized single-particle states, Ann. Physics 321 (2006); J. Z. Imbrie, On many-body localization for quantum spin chains, J. Stat. Phys. 163 (2016)",
 why="Many-body localization would be a robust failure of thermalization in an isolated interacting quantum system, a counterexample to the eigenstate thermalization hypothesis; it is the main open problem joining random operators and quantum statistical mechanics.",
 st="Imbrie (J. Stat. Phys. 163 (2016), arXiv:1403.7837) proved it for the random Ising chain with transverse field under an unproved assumption of limited level attraction. Avalanche arguments (De Roeck–Huveneers 2017) indicate instability in dimension two and higher, and numerics have raised doubts about the 1D transition (Šuntajs–Bonča–Prosen–Vidmar, arXiv:1905.06345, Phys. Rev. E 102 (2020)). Localization at low energies for the random XXZ chain is known (Elgart–Klein–Stolz, arXiv:1708.00474, Comm. Math. Phys. 361 (2018)), with logarithmic light cones at the bottom of the XXZ spectrum (Elgart–Klein, arXiv:2602.01441). Huveneers (arXiv:2609.39462) reviews the state of the question. An unconditional proof at positive energy density is open.",
 n="Statement revised after the w673 audit (14 Oct)."),
]
